/**
 * Generated by `createservice subscription.RegisterSubscriptionContextsService --type mutations`
 */

const dayjs = require('dayjs')
const get = require('lodash/get')

const { GQLError, GQLErrorCode: { BAD_USER_INPUT } } = require('@open-condo/keystone/errors')
const { getLogger } = require('@open-condo/keystone/logging')
const { GQLCustomSchema, find, getById } = require('@open-condo/keystone/schema')

const { registerMultiPayment } = require('@condo/domains/acquiring/utils/serverSchema')
const { NOT_FOUND } = require('@condo/domains/common/constants/errors')
const { INVOICE_STATUS_PUBLISHED, INVOICE_TYPE_B2B } = require('@condo/domains/marketplace/constants')
const { Invoice } = require('@condo/domains/marketplace/utils/serverSchema')
const { Organization } = require('@condo/domains/organization/utils/serverSchema')
const access = require('@condo/domains/subscription/access/RegisterSubscriptionContextsService')
const {
    PERIOD_TO_MONTHS,
    SUBSCRIPTION_CONTEXT_STATUS,
    SUBSCRIPTION_PLAN_TYPE_SERVICE,
    SUBSCRIPTION_PLAN_TYPE_FEATURE,
    SUBSCRIPTION_PAYMENT_TYPE_CARD,
    SUBSCRIPTION_PAYMENT_TYPES,
} = require('@condo/domains/subscription/constants')
const { isPlanSubsetOf } = require('@condo/domains/subscription/utils/isPlanSubsetOf')
const { SubscriptionContext } = require('@condo/domains/subscription/utils/serverSchema')
const { getSubscriptionPaymentRecipient } = require('@condo/domains/subscription/utils/serverSchema/getSubscriptionPaymentRecipient')
const { buildDirectPaymentUrl, calculateSubscriptionStartDate } = require('@condo/domains/subscription/utils/subscriptionContext')

const logger = getLogger('RegisterSubscriptionContextsService')

const ERRORS = {
    ORGANIZATION_NOT_FOUND: {
        mutation: 'registerSubscriptionContexts',
        variable: ['data', 'organization'],
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'Organization not found',
        messageForUser: 'api.subscription.registerSubscriptionContexts.ORGANIZATION_NOT_FOUND',
    },
    PRICING_RULE_NOT_FOUND: {
        mutation: 'registerSubscriptionContexts',
        variable: ['data', 'subscriptionPlanPricingRule'],
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'Subscription plan pricing rule not found',
        messageForUser: 'api.subscription.registerSubscriptionContexts.PRICING_RULE_NOT_FOUND',
    },
    INVALID_ORGANIZATION_TYPE: {
        mutation: 'registerSubscriptionContexts',
        variable: ['data', 'organization'],
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'Organization type does not match subscription plan organization type',
        messageForUser: 'api.subscription.registerSubscriptionContexts.INVALID_ORGANIZATION_TYPE',
    },
    TRIAL_NOT_AVAILABLE: {
        mutation: 'registerSubscriptionContexts',
        variable: ['data', 'isTrial'],
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'Trial subscription is not available for this plan',
        messageForUser: 'api.subscription.registerSubscriptionContexts.TRIAL_NOT_AVAILABLE',
    },
    TRIAL_ALREADY_USED: {
        mutation: 'registerSubscriptionContexts',
        variable: ['data', 'isTrial'],
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'Trial subscription for this plan was already activated',
        messageForUser: 'api.subscription.registerSubscriptionContexts.TRIAL_ALREADY_USED',
    },
    MIXED_PRICING_RULE_PERIODS: {
        mutation: 'registerSubscriptionContexts',
        variable: ['data', 'additionalPricingRules'],
        code: BAD_USER_INPUT,
        type: 'MIXED_PRICING_RULE_PERIODS',
        message: 'All pricing rules in a bundle must have the same period',
        messageForUser: 'api.subscription.registerSubscriptionContexts.MIXED_PRICING_RULE_PERIODS',
    },
    DUPLICATE_PLAN_IN_BUNDLE: {
        mutation: 'registerSubscriptionContexts',
        variable: ['data', 'additionalPricingRules'],
        code: BAD_USER_INPUT,
        type: 'DUPLICATE_PLAN_IN_BUNDLE',
        message: 'A bundle cannot contain the same subscription plan more than once',
        messageForUser: 'api.subscription.registerSubscriptionContexts.DUPLICATE_PLAN_IN_BUNDLE',
    },
    MULTIPLE_SERVICE_PLANS_IN_BUNDLE: {
        mutation: 'registerSubscriptionContexts',
        variable: ['data', 'additionalPricingRules'],
        code: BAD_USER_INPUT,
        type: 'MULTIPLE_SERVICE_PLANS_IN_BUNDLE',
        message: 'A bundle can contain at most one service plan',
        messageForUser: 'api.subscription.registerSubscriptionContexts.MULTIPLE_SERVICE_PLANS_IN_BUNDLE',
    },
    FEATURE_ALREADY_IN_PLAN: {
        mutation: 'registerSubscriptionContexts',
        variable: ['data', 'additionalPricingRules'],
        code: BAD_USER_INPUT,
        type: 'FEATURE_ALREADY_IN_PLAN',
        message: 'A feature plan in the bundle is already covered by another plan in the same bundle',
        messageForUser: 'api.subscription.registerSubscriptionContexts.FEATURE_ALREADY_IN_PLAN',
    },
    NO_ACTIVE_SERVICE_SUBSCRIPTION: {
        mutation: 'registerSubscriptionContexts',
        variable: ['data', 'organization'],
        code: BAD_USER_INPUT,
        type: 'NO_ACTIVE_SERVICE_SUBSCRIPTION',
        message: 'Cannot subscribe to a feature plan without an active service subscription',
        messageForUser: 'api.subscription.registerSubscriptionContexts.NO_ACTIVE_SERVICE_SUBSCRIPTION',
    },
    PAYMENT_RECIPIENT_NOT_CONFIGURED: {
        mutation: 'registerSubscriptionContexts',
        code: BAD_USER_INPUT,
        type: NOT_FOUND,
        message: 'SUBSCRIPTION_PAYMENT_RECIPIENT is not configured',
    },
}

const RegisterSubscriptionContextsService = new GQLCustomSchema('RegisterSubscriptionContextsService', {
    types: [
        {
            access: true,
            type: `enum SubscriptionPaymentType { ${SUBSCRIPTION_PAYMENT_TYPES.join(' ')} }`,
        },
        {
            access: true,
            type: 'input RegisterSubscriptionContextsInput { dv: Int!, sender: SenderFieldInput!, organization: OrganizationWhereUniqueInput!, subscriptionPlanPricingRules: [SubscriptionPlanPricingRuleWhereUniqueInput!]!, paymentType: SubscriptionPaymentType!, isTrial: Boolean }',
        },
        {
            access: true,
            type: 'type RegisterSubscriptionContextsOutput { subscriptionContexts: [SubscriptionContext!]!, directPaymentUrl: String, multiPayment: MultiPayment }',
        },
    ],

    mutations: [
        {
            access: access.canRegisterSubscriptionContexts,
            schema: 'registerSubscriptionContexts(data: RegisterSubscriptionContextsInput!): RegisterSubscriptionContextsOutput',
            doc: {
                summary: 'Registers a subscription for an organization from one or more pricing rules (a bundle). For trials (isTrial=true) creates a status DONE SubscriptionContext for every plan whose trial is available (its own trialDays), skipping plans with no trial or an already used one. For paid subscriptions creates one Invoice with a row per pricing rule and one SubscriptionContext per pricing rule with status CREATED; when paymentType=card a MultiPayment and directPaymentUrl are also created. Every call registers a fresh Invoice + contexts; it does not look at or touch earlier unpaid registrations.',
                errors: ERRORS,
            },
            resolver: async (parent, args, context) => {
                const { data } = args
                const {
                    dv,
                    sender,
                    organization: organizationInput,
                    subscriptionPlanPricingRules: pricingRuleInputs,
                    paymentType,
                    isTrial,
                } = data

                logger.info({ msg: 'Starting subscription registration', data: { organizationId: organizationInput.id, pricingRuleCount: pricingRuleInputs.length, paymentType, isTrial } })

                const [organization] = await find('Organization', {
                    id: organizationInput.id,
                    deletedAt: null,
                })
                if (!organization) {
                    throw new GQLError(ERRORS.ORGANIZATION_NOT_FOUND, context)
                }

                if (pricingRuleInputs.length === 0) {
                    throw new GQLError(ERRORS.PRICING_RULE_NOT_FOUND, context)
                }
                const subscriptions = []
                for (const ruleInput of pricingRuleInputs) {
                    const [rule] = await find('SubscriptionPlanPricingRule', {
                        id: ruleInput.id,
                        deletedAt: null,
                    })
                    if (!rule) {
                        throw new GQLError(ERRORS.PRICING_RULE_NOT_FOUND, context)
                    }
                    const [plan] = await find('SubscriptionPlan', {
                        id: rule.subscriptionPlan,
                        deletedAt: null,
                    })
                    if (!plan) {
                        throw new GQLError(ERRORS.PRICING_RULE_NOT_FOUND, context)
                    }
                    subscriptions.push({ rule, plan })
                }

                for (const { plan } of subscriptions) {
                    if (plan.organizationType && plan.organizationType !== organization.type) {
                        throw new GQLError(ERRORS.INVALID_ORGANIZATION_TYPE, context)
                    }
                }

                const planIds = subscriptions.map(subscription => subscription.plan.id)
                if (new Set(planIds).size !== planIds.length) {
                    throw new GQLError(ERRORS.DUPLICATE_PLAN_IN_BUNDLE, context)
                }

                const serviceSubscriptions = subscriptions.filter(subscription => subscription.plan.planType === SUBSCRIPTION_PLAN_TYPE_SERVICE)
                if (serviceSubscriptions.length > 1) {
                    throw new GQLError(ERRORS.MULTIPLE_SERVICE_PLANS_IN_BUNDLE, context)
                }

                const featureSubscriptions = subscriptions.filter(subscription => subscription.plan.planType === SUBSCRIPTION_PLAN_TYPE_FEATURE)
                for (const featureSubscription of featureSubscriptions) {
                    for (const otherSubscription of subscriptions) {
                        if (otherSubscription.plan.id === featureSubscription.plan.id) continue
                        if (isPlanSubsetOf(featureSubscription.plan, otherSubscription.plan)) {
                            throw new GQLError(ERRORS.FEATURE_ALREADY_IN_PLAN, context)
                        }
                    }
                }

                if (featureSubscriptions.length > 0 && serviceSubscriptions.length === 0) {
                    const organizationData = await Organization.getOne(context, { id: organization.id }, 'id subscription { activeSubscriptionEndAt }')
                    const activeSubscriptionEndAt = get(organizationData, ['subscription', 'activeSubscriptionEndAt'])
                    const hasActiveServiceSubscription = activeSubscriptionEndAt && dayjs(activeSubscriptionEndAt).isAfter(dayjs().startOf('day'))
                    if (!hasActiveServiceSubscription) {
                        throw new GQLError(ERRORS.NO_ACTIVE_SERVICE_SUBSCRIPTION, context)
                    }
                }

                if (isTrial) {
                    const trialSubscriptions = []
                    let anyTrialAlreadyUsed = false
                    for (const subscription of subscriptions) {
                        if (subscription.plan.trialDays <= 0) continue
                        const [existingTrial] = await find('SubscriptionContext', {
                            organization: { id: organization.id },
                            subscriptionPlan: { id: subscription.plan.id },
                            isTrial: true,
                            deletedAt: null,
                        })
                        if (existingTrial) {
                            anyTrialAlreadyUsed = true
                            continue
                        }
                        trialSubscriptions.push(subscription)
                    }
                    if (trialSubscriptions.length === 0) {
                        throw new GQLError(anyTrialAlreadyUsed ? ERRORS.TRIAL_ALREADY_USED : ERRORS.TRIAL_NOT_AVAILABLE, context)
                    }

                    const trialStartAt = dayjs()
                    const createdIds = []
                    for (const { plan } of trialSubscriptions) {
                        const created = await SubscriptionContext.create(context, {
                            dv,
                            sender,
                            organization: { connect: { id: organization.id } },
                            subscriptionPlan: { connect: { id: plan.id } },
                            startAt: trialStartAt.format('YYYY-MM-DD'),
                            endAt: trialStartAt.add(plan.trialDays, 'day').format('YYYY-MM-DD'),
                            isTrial: true,
                            status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
                        })
                        createdIds.push(created.id)
                    }

                    const subscriptionContexts = await find('SubscriptionContext', { id_in: createdIds, deletedAt: null })
                    return { subscriptionContexts, directPaymentUrl: null, multiPayment: null }
                }

                const isCard = paymentType === SUBSCRIPTION_PAYMENT_TYPE_CARD

                const baseSubscription = serviceSubscriptions[0]
                    || [...subscriptions].sort((a, b) => (a.rule.id < b.rule.id ? -1 : 1))[0]

                const period = baseSubscription.rule.period
                for (const { rule } of subscriptions) {
                    if (rule.period !== period) {
                        throw new GQLError(ERRORS.MIXED_PRICING_RULE_PERIODS, context)
                    }
                }
                const months = PERIOD_TO_MONTHS[period]
                if (!months) {
                    throw new GQLError(ERRORS.PRICING_RULE_NOT_FOUND, context)
                }

                const activePaidContexts = await find('SubscriptionContext', {
                    organization: { id: organization.id },
                    subscriptionPlan: { id: baseSubscription.plan.id },
                    status: SUBSCRIPTION_CONTEXT_STATUS.DONE,
                    deletedAt: null,
                })
                const startAt = calculateSubscriptionStartDate(activePaidContexts)
                const startAtStr = startAt.format('YYYY-MM-DD')
                const endAtStr = startAt.add(months, 'month').format('YYYY-MM-DD')

                const { recipientOrgId: recipientOrganizationId } = await getSubscriptionPaymentRecipient()
                if (!recipientOrganizationId) {
                    logger.error({ msg: 'SUBSCRIPTION_PAYMENT_RECIPIENT is not configured' })
                    throw new GQLError(ERRORS.PAYMENT_RECIPIENT_NOT_CONFIGURED, context)
                }

                const invoice = await Invoice.create(context, {
                    dv,
                    sender,
                    organization: { connect: { id: recipientOrganizationId } },
                    type: INVOICE_TYPE_B2B,
                    payerOrganization: { connect: { id: organization.id } },
                    status: INVOICE_STATUS_PUBLISHED,
                    rows: subscriptions.map(({ rule, plan }) => ({
                        name: plan.name,
                        count: 1,
                        toPay: rule.price,
                        isMin: false,
                    })),
                })

                const createdIds = []
                for (const { rule, plan } of subscriptions) {
                    const created = await SubscriptionContext.create(context, {
                        dv,
                        sender,
                        organization: { connect: { id: organization.id } },
                        subscriptionPlan: { connect: { id: plan.id } },
                        subscriptionPlanPricingRule: { connect: { id: rule.id } },
                        invoice: { connect: { id: invoice.id } },
                        startAt: startAtStr,
                        endAt: endAtStr,
                        isTrial: false,
                        status: SUBSCRIPTION_CONTEXT_STATUS.CREATED,
                        frozenPaymentInfo: { pricingRuleId: rule.id },
                    })
                    createdIds.push(created.id)
                }

                let directPaymentUrl = null
                let multiPayment = null
                if (isCard) {
                    const multiPaymentResult = await registerMultiPayment(context, { invoices: [{ id: invoice.id }], sender })
                    directPaymentUrl = buildDirectPaymentUrl(multiPaymentResult.directPaymentUrl, organization.id)
                    multiPayment = await getById('MultiPayment', multiPaymentResult.multiPaymentId)
                }

                const subscriptionContexts = await find('SubscriptionContext', { id_in: createdIds, deletedAt: null })
                logger.info({ msg: 'Registered subscription bundle', data: { organizationId: organization.id, invoiceId: invoice.id, contextCount: subscriptionContexts.length, multiPaymentId: multiPayment?.id || null } })

                return { subscriptionContexts, directPaymentUrl, multiPayment }
            },
        },
    ],

})

module.exports = {
    RegisterSubscriptionContextsService,
    ERRORS,
}
